import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync, } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { clearPreviousResult, LEGACY_RESULT_PATH, parseReplayResult, validateReplayResult, writeCompatibilityResult, } from "./replayResultResolver.js";
let dir;
beforeEach(() => {
    dir = mkdtempSync(join(tmpdir(), "replay-result-"));
});
afterEach(() => {
    rmSync(dir, { recursive: true, force: true });
});
// A minimally valid ReplayResult: an items array plus a testRunId.
const RESULT = { items: [], testRunId: "run-1" };
describe("parseReplayResult", () => {
    it("prefers the result file over this run's stdout", () => {
        const out = join(dir, "result.json");
        writeFileSync(out, JSON.stringify({ ...RESULT, from: "file" }));
        // stdout is deliberately non-JSON; the file must still win.
        const parsed = parseReplayResult(out, "not json at all");
        expect(parsed).toEqual({ ok: true, result: { ...RESULT, from: "file" } });
    });
    it("falls back to stdout JSON and writes a compatibility file at out", () => {
        const out = join(dir, "missing.json");
        const parsed = parseReplayResult(out, JSON.stringify({ ...RESULT, from: "stdout" }));
        expect(parsed).toEqual({ ok: true, result: { ...RESULT, from: "stdout" } });
        // The parsed stdout is mirrored to out so downstream file consumers see it.
        expect(JSON.parse(readFileSync(out, "utf8"))).toEqual({
            ...RESULT,
            from: "stdout",
        });
    });
    it("recovers ReplayResult JSON printed after a package-runner banner", () => {
        const out = join(dir, "missing.json");
        const body = `> my-app@1.0.0 replay\n> tsx scripts/replay.ts\n${JSON.stringify(RESULT)}`;
        expect(parseReplayResult(out, body)).toEqual({ ok: true, result: RESULT });
    });
    it("rejects stdout that is JSON but not a ReplayResult", () => {
        // A dependency's log line or config dump must never count as the result.
        const cwd = process.cwd();
        process.chdir(dir);
        try {
            expect(parseReplayResult(join(dir, "none.json"), '{"level":"info"}')).toEqual({
                ok: false,
            });
        }
        finally {
            process.chdir(cwd);
        }
    });
    it("returns ok:false when there is no file and stdout is not JSON", () => {
        // Run from an empty cwd so the relative legacy path resolves to nothing.
        const cwd = process.cwd();
        process.chdir(dir);
        try {
            const parsed = parseReplayResult(join(dir, "none.json"), "human summary");
            expect(parsed).toEqual({ ok: false });
        }
        finally {
            process.chdir(cwd);
        }
    });
    it("returns ok:false with no output and no file", () => {
        const cwd = process.cwd();
        process.chdir(dir);
        try {
            expect(parseReplayResult(join(dir, "none.json"), "")).toEqual({
                ok: false,
            });
        }
        finally {
            process.chdir(cwd);
        }
    });
});
describe("clearPreviousResult", () => {
    it("removes an existing result and no-ops on undefined or a missing path", () => {
        const out = join(dir, "stale.json");
        writeFileSync(out, "{}");
        clearPreviousResult(out);
        expect(existsSync(out)).toBe(false);
        expect(() => clearPreviousResult(undefined)).not.toThrow();
        expect(() => clearPreviousResult(join(dir, "never.json"))).not.toThrow();
    });
});
describe("writeCompatibilityResult", () => {
    it("writes the body to out and no-ops on undefined", () => {
        const out = join(dir, "nested", "compat.json");
        writeCompatibilityResult(out, '{"a":1}');
        expect(readFileSync(out, "utf8")).toBe('{"a":1}');
        expect(() => writeCompatibilityResult(undefined, "{}")).not.toThrow();
    });
});
describe("LEGACY_RESULT_PATH", () => {
    it("is the fixed pre-run-dir fallback location", () => {
        expect(LEGACY_RESULT_PATH).toBe("scripts/replay-result.json");
    });
});
describe("validateReplayResult", () => {
    it("accepts a result with items and a testRunId, keeping extra fields", () => {
        expect(validateReplayResult({ items: [], testRunId: "run-1", testRunUrl: "u" })).toEqual({
            ok: true,
            result: { items: [], testRunId: "run-1", testRunUrl: "u" },
        });
    });
    it("accepts the snake_case test_run_id alias", () => {
        expect(validateReplayResult({ items: [{}], test_run_id: "run-2" })).toEqual({
            ok: true,
            result: { items: [{}], test_run_id: "run-2" },
        });
    });
    it("rejects a result missing the items array", () => {
        expect(validateReplayResult({ testRunId: "run-1" })).toEqual({ ok: false });
    });
    it("rejects a result with no test-run id", () => {
        expect(validateReplayResult({ items: [] })).toEqual({ ok: false });
    });
    it("rejects non-objects and arbitrary JSON blobs", () => {
        for (const v of [null, undefined, 42, "x", [], { level: "info" }]) {
            expect(validateReplayResult(v)).toEqual({ ok: false });
        }
    });
});
